const operationTable: Record<string, (w: WorldState) => WorldState> = {
  advanceVok1,
  advanceVok2,
  advanceZef1,
  advanceZef2,
  advanceTal1,
  advanceOsk1,
  advanceFen1,
  advanceFen2,
  advanceOskFen,
